package io.invenlio.receiving;import jakarta.servlet.http.HttpServletRequest;import java.net.URI;import java.util.Set;import org.slf4j.MDC;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestControllerAdvice class ReceivingExceptionHandler{private static final Set<String>C=Set.of("CONCURRENT_MODIFICATION","IDEMPOTENCY_KEY_REUSED","PURCHASE_ORDER_OVER_RECEIPT","INSUFFICIENT_ON_HAND","PUT_AWAY_QUANTITY_EXCEEDED");@ExceptionHandler(ReceivingException.class)ResponseEntity<ProblemDetail>handle(ReceivingException e,HttpServletRequest r){HttpStatus s=e.code().endsWith("NOT_FOUND")?HttpStatus.NOT_FOUND:C.contains(e.code())?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;ProblemDetail p=ProblemDetail.forStatusAndDetail(s,e.getMessage());p.setType(URI.create("https://invenlio.io/problems/"+e.code().toLowerCase().replace('_','-')));p.setTitle(s.getReasonPhrase());p.setInstance(URI.create(r.getRequestURI()));p.setProperty("code",e.code());p.setProperty("correlationId",MDC.get("correlationId"));return ResponseEntity.status(s).contentType(MediaType.APPLICATION_PROBLEM_JSON).body(p);}}
